const positions = $('Postgres: Load Portfolio').all();

// Group positions by symbol (user may have multiple positions per symbol)
const bySymbol = {};
for (const item of positions) {
  const p = item.json;
  if (!bySymbol[p.symbol]) {
    bySymbol[p.symbol] = {
      symbol: p.symbol,
      name: p.security_name,
      positions: []
    };
  }
  bySymbol[p.symbol].positions.push({
    qty: p.qty,
    avgCost: p.avg_cost,
    pnlPercent: p.pnl_percent,
    currentPrice: p.current_price,
    timeHorizon: p.time_horizon,
    thesis: p.thesis,
    triggers: p.triggers,
    notes: p.notes
  });
}

// Format as readable string for AI
const lines = [];
for (const [symbol, data] of Object.entries(bySymbol)) {
  for (const pos of data.positions) {
    const pnlStr = pos.pnlPercent >= 0 ? `+${pos.pnlPercent}%` : `${pos.pnlPercent}%`;
    lines.push(`${symbol} | ${pos.timeHorizon || 'unknown'} | ${pnlStr} | Thesis: ${pos.thesis || 'Not specified'}`);
    if (pos.triggers && pos.triggers.length > 0) {
      lines.push(`  Triggers: ${JSON.stringify(pos.triggers)}`);
    }
  }
}

return [{
  json: {
    portfolioContext: lines.join('\n'),
    symbolList: Object.keys(bySymbol),
    positionCount: positions.length
  }
}];

