// === NEW: Clean and truncate email body ===
const cleanBody = (text) => {
  if (!text) return '';

  // 1. Remove HTML tags
  let cleaned = text.replace(/<[^>]*>/g, ' ');

  // 2. Decode HTML entities
  cleaned = cleaned
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"');

  // 3. Remove common newsletter boilerplate
  cleaned = cleaned
    .replace(/unsubscribe|view in browser|view online|privacy policy|manage preferences|update your preferences/gi, '')
    .replace(/©\s*\d{4}[^.]*\./g, '') // Copyright notices
    .replace(/all rights reserved/gi, '')
    .replace(/\*{5,}/g, '');

  // 4. Replace URLs with placeholder (keep info, save tokens)
  cleaned = cleaned.replace(/https?:\/\/[^\s]+/g, '[link]');

  // 5. Clean excessive whitespace
  cleaned = cleaned.replace(/\s+/g, ' ').trim();

  return cleaned;
};

const originalLength = body.length;
let cleanedBody = cleanBody(body);
const cleanedLength = cleanedBody.length;

// Truncate to 5000 chars
const maxLength = 5000;
const wasTruncated = cleanedBody.length > maxLength;
if (wasTruncated) {
  cleanedBody = cleanedBody.substring(0, maxLength) + '\n\n[...truncated, ' + (cleanedLength - maxLength) + ' chars removed]';
}

return {
  json: {
    sourceType,
    subject,
    body: cleanedBody,
    from,
    emailDate,
