const config = $('Config: Settings').first().json;
const triage = $('Guard: Triage').first().json;
const analysis = $('Guard: Analysis').first().json;

const weights = config.scoring.weights;

// Calculate max scores across all actions
let maxUrgency = 0;
let maxRelevance = 0;
let maxMateriality = 0;
let maxConfidence = 0;
let watchlistHit = null;
const symbolsImpacted = [];
const thesisImpacts = [];
const categoriesFound = new Set(triage.categories || []);

for (const action of analysis.actions || []) {
  maxUrgency = Math.max(maxUrgency, action.urgencyScore || 0);
  maxRelevance = Math.max(maxRelevance, action.relevanceScore || 0);
  maxMateriality = Math.max(maxMateriality, action.materialityScore || 0);
  maxConfidence = Math.max(maxConfidence, action.confidence || 0);

  if (!symbolsImpacted.includes(action.symbol)) {
    symbolsImpacted.push(action.symbol);
  }

  thesisImpacts.push({
    symbol: action.symbol,
    impact: action.thesisImpact
  });

  if (action.category) {
    categoriesFound.add(action.category);
  }

  // Check watchlist
  if (config.immediateAlerts.watchlistSymbols.includes(action.symbol)) {
    watchlistHit = action.symbol;
  }
}

// Calculate composite score
const compositeScore = Math.round(
  (maxRelevance * weights.relevance) +
  (maxMateriality * weights.materiality) +
  (maxUrgency * weights.urgency) +
  ((triage.confidence || 0.5) * 100 * weights.confidence)
);

// Determine if immediate alert needed
const urgencyTriggered = maxUrgency > config.immediateAlerts.urgencyThreshold;
const shouldAlertImmediately = config.immediateAlerts.enabled &&
  (urgencyTriggered || watchlistHit !== null);

const alertReason = urgencyTriggered
  ? 'urgency_threshold'
  : watchlistHit
    ? 'watchlist_symbol'
    : null;

return {
  json: {
    maxUrgency,
    maxRelevance,
    maxMateriality,
    maxConfidence,
    compositeScore,
    shouldAlertImmediately,
    alertReason,
    watchlistHit,
    symbolsImpacted,
    thesisImpacts,
    categories: Array.from(categoriesFound)
  }
};

