const runInfo = $('Generate Run ID').first().json;
const input = $('Format Input').first().json;
const triage = $('Guard: Triage').first().json;
const analysis = $('Guard: Analysis').first().json;
const scores = $('Calculate Scores').first().json;

// Helper to escape single quotes for SQL
const esc = (str) => {
  if (str === null || str === undefined) return '';
  if (typeof str === 'object') {
    // Handle objects like Gmail's from field
    return JSON.stringify(str).replace(/'/g, "''");
  }
  return String(str).replace(/'/g, "''");
};

// Extract email address from from field (could be object or string)
let emailFrom = input.from;
if (typeof emailFrom === 'object') {
  emailFrom = emailFrom.emailAddress || emailFrom.email || emailFrom.value?.[0]?.address ||
JSON.stringify(emailFrom);
}

