const analysis = $('Guard: Analysis').first().json;
const scores = $('Calculate Scores').first().json;

// Build UPSERT statements for each symbol+category combination
const upserts = [];

for (const action of analysis.actions || []) {
  const symbol = action.symbol;
  const category = action.category || 'other';
  const compositeScore = scores.compositeScore || 0;

  // Determine thesis impact column to increment
  let thesisColumn;
  if (action.thesisImpact === 'validates') {
    thesisColumn = 'validates_count';
  } else if (action.thesisImpact === 'challenges') {
    thesisColumn = 'challenges_count';
  } else {
    thesisColumn = 'neutral_count';
  }

  upserts.push({
    symbol,
    category,
    compositeScore,
    thesisColumn
  });
}

return {
  json: {
    upserts,
    hasPatterns: upserts.length > 0
  }
};

const upserts = $('Update Pattern History').first().json.upserts;

// Build a single query with multiple UPSERTs
const statements = upserts.map(u => `
  INSERT INTO invest_audit.investing_news_pattern_history (symbol, news_category, total_composite_score,
${u.thesisColumn})
  VALUES ('${u.symbol}', '${u.category}', ${u.compositeScore}, 1)
  ON CONFLICT (symbol, news_category) DO UPDATE SET
    occurrence_count = investing_news_pattern_history.occurrence_count + 1,
    last_seen_at = NOW(),
    total_composite_score = investing_news_pattern_history.total_composite_score + ${u.compositeScore},
    ${u.thesisColumn} = investing_news_pattern_history.${u.thesisColumn} + 1
`).join('; ');

return {
  json: {
    query: statements
  }
};
